1402	/// Remove every tmp tarball file that a partially-completed publish
1403	/// already wrote. Errors are swallowed: the caller is already
1404	/// returning an error response, and a leftover `*.tmp.*` file is
1405	/// harmless beyond a small amount of disk.
1406	async fn cleanup_tmp_slots(slots: Vec<crate::storage::TarballSlot>) {
1407	    for slot in slots {
