1433	        return Response::builder()
1434	            .status(StatusCode::OK)
1435	            .header(header::CONTENT_TYPE, "application/json")
1436	            .body(Body::from(bytes))
1437	            .expect("static-shape response always builds");
1438	    };
1439	    let size = crate::search::parse_size(query_string, 20);
1440	    let mut body = match crate::search::run_local_search(&state.inner.storage, &text, size).await {
1441	        Ok(body) => body,
1442	        Err(err) => return error_response(&err),
1443	    };
