/// * OSV lists `name@key` as vulnerable.
fn filter_packument_for_osv(packument: &mut Value, name: &str, osv: &crate::resolver::OsvIndex) {
    let Some(obj) = packument.as_object_mut() else {
        return;
    };
    let mut removed: std::collections::HashSet<String> = std::collections::HashSet::new();
    if let Some(versions) = obj.get_mut("versions").and_then(Value::as_object_mut) {
