            if !keep {
                removed.insert(version_key.clone());
            }
            keep
        });
    }
    if removed.is_empty() {
        return;
    }
    if let Some(time) = obj.get_mut("time").and_then(Value::as_object_mut) {
        // `modified` / `created` are never version keys, so they survive.
        time.retain(|key, _| !removed.contains(key));
    }
    if let Some(tags) = obj.get_mut("dist-tags").and_then(Value::as_object_mut) {
        tags.retain(|_tag, target| {
            target.as_str().is_none_or(|version| !removed.contains(version))
        });
    }
