/// Whether a packument version entry is well-formed enough to keep: its
/// key must be a valid semver and must match the entry's own `version`
/// field. Anything else can't be reliably screened against OSV, so it is
/// dropped rather than served unchecked.
fn version_entry_is_eligible(version_key: &str, entry: &Value) -> bool {
    if node_semver::Version::parse(version_key).is_err() {
        return false;
    }
    entry.get("version").and_then(Value::as_str) == Some(version_key)
}

/// 403 response for a tarball whose version OSV flags as vulnerable. The
/// body carries the advisory id(s) so the client sees *why* the download
/// was refused; no upstream request is made for a refused tarball.
fn osv_forbidden_response(name: &str, version: &str, ids: &[String]) -> Response {
    let message = format!(
        "{name}@{version} is listed in the local OSV database as vulnerable ({})",
        crate::resolver::format_advisory_ids(ids),
    );
    let bytes = serde_json::to_vec(&json!({ "error": message })).expect("static-shape JSON serializes");
    Response::builder()
        .status(StatusCode::FORBIDDEN)
        .header(header::CONTENT_TYPE, "application/json")
        .body(Body::from(bytes))
        .expect("static-shape response always builds")
}

